status = {"schema": "nexus.elliott-v9-first-producer-parent-status.v1", "state": "STAGING",
          "started_at_utc": now(), "run_root": str(ROOT), "source_sha": freeze["source_sha"],
          "parent_pid": os.getpid(), "wrapper_pid": None, "wrapper_actual_os_exit_code": None,
          "market_producer_exit_self_asserted": False, "research_only": True, "live_enabled": False}
def checkpoint(phase, **extra):
    status.update(state=phase, observed_at_utc=now(), elapsed_seconds=round(time.monotonic()-start, 3), **extra)
    put(ROOT / "parent-status.json", status)

